(()=>{
'use strict';
const API='https://labour-dispute-games.darrin-dookie.chatgpt.site';
const SITE='https://darrindookie-itcilo.github.io/Labour-Dispute-Resolution-Games/';
const $=id=>document.getElementById(id), main=$('main');
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let storageOK=true;
const save=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));}catch{storageOK=false;}};
let practices=load('ldg-practice-v2',{}), connections=load('ldg-connections-v2',[]), imports=load('ldg-imports-v2',[]);
let adminToken='';try{adminToken=sessionStorage.getItem('ldg-admin-v2')||'';}catch{}
let ui={mode:'practice',game:'diagnostic',live:null,selected:'',reason:'',confidence:'sure',busy:false,error:'',offline:false,board:null,rooms:[],roomCode:'',projector:false,setupCount:13,adminGame:'diagnostic',standings:null,sound:false,create:{name:'22 October · Session 10',game:'diagnostic',count:13,scenario:'all',startStage:0,minutes:15},openDetails:new Set()};
try{const p=JSON.parse(sessionStorage.getItem('ldg-pointer-v2'));if(p){ui.mode=p.mode;ui.game=p.game;ui.live=connections.find(c=>c.team.id===p.id)||null;}ui.roomCode=sessionStorage.getItem('ldg-room-v2')||'';}catch{}
const fmt=seconds=>{seconds=Math.max(0,Math.floor(seconds||0));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');};
const gameName=g=>g==='diagnostic'?'The Diagnostic':'Stop the Escalation';
const principle=id=>DATA.PRINCIPLES.find(p=>p.id===id);
const card=id=>DATA.CARDS.find(p=>p.id===id);
const symptom=ref=>DATA.SYMPTOMS.find(p=>p.ref===ref);
const active=()=>ui.mode==='live'?ui.live?.team.state:practices[ui.game];
const button=(action,label,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const disabled=()=>ui.busy||!!ui.live?.pending&&ui.mode==='live'||ui.mode==='live'&&ui.live?.room.status!=='open';
const no=(condition)=>condition?' disabled':'';
function persist(){save('ldg-practice-v2',practices);if(ui.live){const i=connections.findIndex(c=>c.team.id===ui.live.team.id);if(i>=0)connections[i]=ui.live;else connections.push(ui.live);save('ldg-connections-v2',connections);}try{sessionStorage.setItem('ldg-pointer-v2',JSON.stringify({mode:ui.mode,game:ui.game,id:ui.live?.team.id}));}catch{}}
let toastTimeout, audio;
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('visible'),4200);}
function tone(good){if(!ui.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.value=good?620:230;g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.start();o.stop(audio.currentTime+.19);}catch{}}
async function confirmAction(title,copy){const d=$('confirm');$('confirm-title').textContent=title;$('confirm-copy').textContent=copy;d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true}));}
async function api(path,{method='GET',data,token=''}={}){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
 try{const response=await fetch(API+'/api'+path,{method,headers:{...(data?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:data?JSON.stringify(data):undefined,signal:controller.signal,credentials:'omit'});let value;try{value=await response.json();}catch{throw Error('The results service returned an unexpected response. Try again.');}if(!response.ok){const error=Error(value.error||'The request could not be completed.');error.status=response.status;error.result=value;throw error;}return value;}catch(err){if(err.name==='AbortError')throw Error('The connection timed out. Your saved move can be retried.');if(err instanceof TypeError)throw Error('The results service is unavailable. Check your internet connection.');throw err;}finally{clearTimeout(timer);}
}
function route(){return location.hash.slice(1).split('?')[0]||'hub';}
function go(hash){ui.error='';if(location.hash==='#'+hash){render();}else location.hash=hash;window.scrollTo(0,0);}
function errHTML(){return ui.error?`<div class="notice warning" role="alert">${e(ui.error)}</div>`:'';}
function savedHTML(){let content='';for(const [game,state] of Object.entries(practices)){if(state?.version===2)content+=button('resume-practice',`Resume ${e(state.team)} · ${gameName(game)}`,'btn secondary small',`data-game="${game}"`);}for(const c of connections.slice(-4)){content+=button('resume-live',`Resume ${e(c.team.name)} · ${e(c.room.code)}`,'btn secondary small',`data-id="${e(c.team.id)}"`);}return content?`<div class="saved-grid">${content}</div>`:'';}
function hub(){
 const room=new URLSearchParams(location.search).get('room')||'';
 return `${errHTML()}<section class="hero"><div><p class="eyebrow">Industrial relations · Team challenges</p><h1>Every dispute has a turning point.</h1><p class="lead">Find the weakness in a national system. Then stop a workplace dispute before it grows. Two games. One conversation worth having.</p><div class="hero-label">22 OCTOBER 2026 · TURIN · FKE</div></div><div class="case-art" aria-hidden="true"><div class="art-sheet"><span>NATIONAL SYSTEM</span><b>13</b><span>PRINCIPLES TO TEST</span><div class="line"></div><div class="line" style="width:70%"></div></div><div class="art-sheet front"><span>WORKPLACE DISPUTE</span><b>11</b><span>MOVES IN YOUR HAND</span><div class="line"></div><div class="seal">Choose your moment.</div></div></div></section>${savedHTML()}<div class="grid-two"><article class="game-card"><div class="accent"></div><div class="body"><div class="card-top"><span class="tag">Session 10 · National systems</span><span class="game-num">01</span></div><h2>The Diagnostic</h2><p>A missing case file. A 400 km journey. An arbitrator with a connection. Diagnose the principle each fictional case puts at risk.</p><div class="tags"><span class="tag">18 case files</span><span class="tag">2 lifelines</span><span class="tag">10–18 min</span></div><a class="btn" href="#diagnostic">Open the case file <span aria-hidden="true">→</span></a></div></article><article class="game-card teal"><div class="accent"></div><div class="body"><div class="card-top"><span class="tag">Session 11 · Workplace systems</span><span class="game-num">02</span></div><h2>Stop the Escalation</h2><p>A roster, a dismissal, a restructure. Read the room, play your intervention and keep the cost of each dispute as low as you can.</p><div class="tags"><span class="tag">3 disputes</span><span class="tag">11 move cards</span><span class="tag">12–20 min</span></div><a class="btn" href="#escalation">Choose your moves <span aria-hidden="true">→</span></a></div></article></div><section class="panel join-panel"><div><p class="eyebrow">Play with the room</p><h2>One team. One device.</h2><p class="muted small">Enter the session code from your facilitator. Your choices, reasons and results will appear on their protected board. Use a team alias.</p></div><form id="join-form" class="join-form"><label>Team name<input name="team" id="join-name" maxlength="40" placeholder="e.g. Table 2" required autocomplete="off"></label><label>Session code<input name="room" id="join-room" maxlength="8" value="${e(room.toUpperCase())}" placeholder="8 characters" required autocapitalize="characters" spellcheck="false" autocomplete="off"></label><button class="btn" ${no(ui.busy)}>Join session</button><p class="join-note">No participant account needed. Practice games save on your device.</p></form></section><div class="section small muted">Three teams of three work well. Compare your reasoning as well as your score. <a href="#guide">Read the quick guide</a>.</div>`;
}
function setup(game){const dx=game==='diagnostic';return `<a class="back" href="#hub">← All games</a><section class="panel setup"><p class="eyebrow">${dx?'Game 01 · National system diagnosis':'Game 02 · Workplace intervention'}</p><h1>${gameName(game)}</h1><p class="lead">${dx?'Choose the principle most directly at risk. Each correct answer earns two points, or one after a lifeline. Both defensible answers are accepted in the ambiguous case.':'Discuss the dispute, choose one intervention and lock it in. A move may resolve it, hold it or allow it to advance. Every card can be used once per dispute.'}</p>${errHTML()}<form id="practice-form" data-game="${game}"><div class="fields"><label>Team name<input name="team" maxlength="40" value="${e(practices[game]?.team||'')}" placeholder="e.g. Table 1" required autocomplete="off"></label><label>Case order code<input name="seed" maxlength="40" value="workshop-2026" autocomplete="off"><small>Use the same code and settings for a fair comparison.</small></label>${dx?`<div class="wide"><span class="field-title">How many case files?</span><div class="choice-row">${[8,13,18].map(n=>button('setup-count',`<b>${n} cases</b><span>${n===8?'Quick round':n===13?'All 13 principles':'The full case file'}</span>`,'choice',`type="button" data-count="${n}" aria-pressed="${ui.setupCount===n}"`)).join('')}</div></div>`:`<label>Dispute<select name="scenario"><option value="all">All three · Campaign</option>${DATA.SCENARIOS.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><label>Start at<select name="startStage"><option value="0">Stage 1 · First warning</option><option value="2">Stage 3 · Formal dispute</option><option value="4">Stage 5 · Last chance</option></select></label>`}</div><div class="rules"><div class="rule"><b>1. Discuss</b>Agree what the problem is before clicking.</div><div class="rule"><b>2. Commit</b>Select a ${dx?'principle':'card'} and lock it in.</div><div class="rule"><b>3. Compare</b>Use the feedback to explain your reasoning.</div></div><div class="actions"><button class="btn" type="submit">Start ${dx?'diagnosing':'the challenge'} →</button></div></form><p class="small muted section">${dx?'The 13-case mode includes one case for every principle. The full mode includes all 18 cases.':'The cost index is a game device, not a financial estimate. A sound process can be valuable even when the parties do not settle.'} Practice runs on this device; join a session from the home page to share with your facilitator.</p></section>`;}
function gameChrome(s){const st=summary(DATA,s),live=ui.mode==='live',r=ui.live?.room;
 return `<div class="game-top"><div><p class="eyebrow">${live?'Live session · '+e(r.code):'Practice · Saved on this device'}</p><h1>${gameName(s.game)}</h1></div><div class="actions" style="margin:0"><span class="connection"><i class="dot"></i>${live?(ui.offline?'Reconnecting':'Connected'):'Local practice'}</span>${button('pause-home','Pause & return','btn secondary small')}</div></div>${errHTML()}${!storageOK?'<div class="notice warning">Browser storage is unavailable. Export your result before closing this page.</div>':''}${live&&r.status!=='open'?`<div class="notice warning">${r.status==='paused'?'The facilitator has paused this session. Take a moment to compare your reasoning.':'This session is closed. You can review and export your progress.'}</div>`:''}${live&&ui.live.pending?`<div class="notice warning">Your move is saved on this device and is waiting to be confirmed by the results service. ${button('retry','Retry saved move','btn secondary small')}</div>`:''}<div class="hud"><div class="stat team"><small>Team</small><b>${e(s.team)}</b></div><div class="stat"><small>${s.game==='diagnostic'?'Learning points':'Dispute'}</small><b>${s.game==='diagnostic'?s.score+' / '+st.max:(s.scenarioIndex+1)+' / '+s.scenarios.length}</b></div><div class="stat"><small>${s.game==='diagnostic'?'Case file':'Cost exposure'}</small><b>${s.game==='diagnostic'?(s.index+1)+' / '+s.deck.length:(s.feedback?.cost??costFor(DATA,s))}</b></div><div class="stat"><small>${live?'Room timer':'Elapsed'}</small><b ${live?'data-room-clock':'data-elapsed'}>${live?fmt(roomSeconds(r)):fmt(st.elapsed)}</b></div></div>`;
}
function roomSeconds(r){return Math.max(0,((r.deadline?r.deadline-Date.now():r.remaining)||0)/1000);}
function reasonBlock(){return `<div class="commit"><label>Our reason <small>(optional)</small><textarea id="reason" maxlength="500" placeholder="Which detail makes this your best choice?">${e(ui.reason)}</textarea></label></div>`;}
function diagnostic(s){const c=symptom(s.deck[s.index]),answered=s.phase==='feedback';return gameChrome(s)+`<div class="progress" aria-label="Cases completed"><i style="width:${s.log.length/s.deck.length*100}%"></i></div><div class="case-layout"><section class="panel case-content fade-in"><div class="case-stamp"><p class="eyebrow">Case file ${e(c.ref)}</p><span class="tag">${answered?'Decision recorded':'Choose one principle'}</span></div><h2 class="case-prompt">${e(c.text)}</h2><div class="principles" role="group" aria-label="Effectiveness principles">${DATA.PRINCIPLES.map(p=>{const correct=answered&&c.answer.includes(p.id),incorrect=answered&&s.feedback.picked===p.id&&!correct;return button('select-principle',`<em>${String(p.n).padStart(2,'0')}</em><span>${e(p.name)}${correct?' ✓':''}${incorrect?' ×':''}</span>`,'principle'+(ui.selected===p.id&&!answered?' selected':'')+(correct?' correct':'')+(incorrect?' incorrect':''),`data-choice="${p.id}" aria-pressed="${(answered?s.feedback.picked===p.id:ui.selected===p.id)}" ${no(answered||s.disabled.includes(p.id)||disabled())}`);}).join('')}</div>${answered?dxFeedback(s,c):`${reasonBlock()}<div class="confidence"><label><input type="radio" name="confidence" value="sure" ${ui.confidence==='sure'?'checked':''}>We agree</label><label><input type="radio" name="confidence" value="discussing" ${ui.confidence==='discussing'?'checked':''}>Still debating</label></div><div class="lock-row">${button('commit-dx','Lock in our diagnosis →','btn',no(!ui.selected||disabled()))}${button('hint',s.hinted?'Lifeline used':`Narrow it down · ${s.lifelines} left`,'btn secondary hint-button',no(s.hinted||!s.lifelines||disabled()))}</div>`}</section><aside class="side-note"><h3>Read the symptom</h3><p>More than one principle can be relevant. Choose the one most directly illustrated by the details.</p><ol><li>Separate structural influence from bias in a particular case.</li><li>Separate speed from how resources are used.</li><li>Ask what would actually need to change.</li></ol>${s.bestStreak>1?`<hr class="divider"><p><strong>${s.bestStreak} correct in a row</strong><br>Your longest streak so far.</p>`:''}</aside></div>`;}
function dxFeedback(s,c){const f=s.feedback,names=c.answer.map(id=>principle(id).name).join(' or ');return `<div class="feedback ${f.right?'good':'bad'}" role="region" aria-labelledby="feedback-title"><h3 id="feedback-title" tabindex="-1">${f.right?`Correct · +${f.points} ${f.points===1?'point':'points'}`:'A different diagnosis'}</h3><p>${f.right?'Accepted answer:':'You chose '+e(principle(f.picked).name)+'. The accepted diagnosis is'} <strong>${e(names)}</strong>.</p><p>${e(c.why)}</p>${c.answer.map(id=>`<div class="def"><strong>${e(principle(id).name)}</strong> · ${e(principle(id).def)}</div>`).join('')}${s.streak>=3?`<p class="streak section">${s.streak} correct in a row</p>`:''}</div><div class="actions">${button('next',s.index+1===s.deck.length?'See our report →':'Next case →','btn',no(disabled()))}</div>`;}
function escalation(s){const sc=currentScenario(DATA,s),answered=s.phase==='feedback';return gameChrome(s)+`<div class="cost-ladder" aria-label="Illustrative cost ladder">${[1,3,9,26,70,200].map((v,i)=>`<div class="cost-step ${i<=s.stage?'on':''} ${i>=3&&i<=s.stage?'hot':''} ${i===s.stage?'active':''}">${v}</div>`).join('')}</div><section class="panel case-content fade-in"><div class="case-stamp"><p class="eyebrow">${e(sc.name)} · Stage ${s.stage+1} of 5</p><span class="tag">${e(DATA.TIERS[s.stage].label)}</span></div><h2 class="case-prompt">${e(sc.stages[s.stage].text)}</h2><p class="small muted">${11-s.used.length} interventions left in this dispute. Discuss the timing as well as the tool.</p><div class="hand" role="group" aria-label="Intervention cards">${shuffled(DATA.CARDS,rng(s.settings.seed+sc.id)).map(c=>{const used=s.used.includes(c.id);return button('select-move',`<span class="move-top"><span>${String(DATA.CARDS.indexOf(c)+1).padStart(2,'0')}</span><span class="badge">${e(c.src)}</span></span><strong>${e(c.name)}</strong><span class="desc">${e(c.desc)}</span>${used?'<span class="used-mark">Played in this dispute</span>':''}`,'move'+(ui.selected===c.id&&!answered?' selected':'')+(used?' used':''),`data-choice="${c.id}" aria-pressed="${ui.selected===c.id}" ${no(used||answered||disabled())}`);}).join('')}</div>${answered?esFeedback(s,sc):`${reasonBlock()}<div class="selection-line" id="selection-line">${ui.selected?'Selected: '+e(card(ui.selected).name):'Select a card to discuss, then lock it in.'}</div><div class="actions">${button('commit-es','Play our intervention →','btn',no(!ui.selected||disabled()))}</div>`}</section>`;}
function esFeedback(s,sc){const f=s.feedback,kind=f.kind,good=kind==='resolve',terminal=f.terminal;return `<div class="feedback ${good?'good':kind==='hold'?'hold':'bad'}" role="region" aria-labelledby="feedback-title"><p class="eyebrow">${e(card(f.card).name)}</p><h3 id="feedback-title" tabindex="-1">${good?'Resolved in this case':kind==='hold'?'Held · Not yet resolved':terminal?'It reached the next forum':'The dispute advances'}</h3><p>${e(f.msg)}</p>${terminal&&!good?`<p>${e(sc.fail)}</p>`:''}<div class="def">${good?'Stopped at stage '+(s.stage+1):'Cost exposure now'} · <strong>${f.cost}</strong> cost index${kind==='hold'?' · A holding move adds 2':''}</div></div><div class="actions">${button('next',terminal?(s.scenarioIndex+1===s.scenarios.length?'See our report →':'Next dispute →'):kind==='hold'?'Try another intervention →':'Next stage →','btn',no(disabled()))}</div><p class="small muted section">This round assumes the facts described and the parties’ response in the feedback. Timing and context can make another intervention defensible; bring your argument to the debrief.</p>`;}
function reviewDX(log){const c=symptom(log.ref);return `<details class="review"><summary><span class="badge ${log.right?'good':'bad'}">${log.points} / 2</span> <strong>${e(log.ref)}</strong> · ${e(principle(log.choice)?.name||log.choice)}${log.hint?' · lifeline':''}${log.confidence==='discussing'?' · debated':''}</summary><div class="review-body"><p>${e(c?.text)}</p><p><strong>Accepted:</strong> ${e(c?.answer.map(id=>principle(id).name).join(' or '))}</p><p>${e(c?.why)}</p>${log.reason?`<p><strong>Your reason:</strong> ${e(log.reason)}</p>`:''}</div></details>`;}
function reviewES(log){return `<details class="review"><summary><span class="badge ${log.kind==='resolve'?'good':log.kind==='hold'?'hold':'bad'}">${log.kind==='resolve'?'Resolved':log.kind==='hold'?'Held':'Advanced'}</span> ${e(DATA.SCENARIOS.find(s=>s.id===log.scenario)?.name)} · Stage ${log.stage+1} · <strong>${e(card(log.card)?.name)}</strong></summary><div class="review-body"><p>${e(log.msg)}</p><p>Cost exposure: <strong>${log.cost}</strong></p>${log.reason?`<p><strong>Your reason:</strong> ${e(log.reason)}</p>`:''}</div></details>`;}
function results(s){const st=summary(DATA,s),dx=s.game==='diagnostic',complete=s.phase==='done';return `<a class="back" href="#hub">← All games</a>${errHTML()}<section class="result-hero"><p class="eyebrow">${e(s.team)} · ${complete?'Challenge complete':'Progress report'}</p><h1>${dx?'Your system diagnosis':'Your intervention report'}</h1><div class="big-score">${dx?`${st.score}<span> / ${st.max}</span>`:`${st.cost}<span> cost index</span>`}</div><p>${dx?`${st.correct} of ${st.total} cases diagnosed correctly. Review the choices your team debated.`:`${st.resolved} of ${st.total} disputes resolved in this campaign. Lower cost means the dispute was addressed earlier.`}</p><div class="metrics"><div class="metric"><b>${dx?st.correct:st.resolved}</b>${dx?'Correct diagnoses':'Disputes resolved'}</div><div class="metric"><b>${dx?s.bestStreak:st.progress}</b>${dx?'Longest streak':'Disputes completed'}</div><div class="metric"><b>${fmt(st.elapsed)}</b>Elapsed time</div></div></section>${!dx?`<div class="grid-two">${s.scenarioResults.map(r=>`<div class="panel"><p class="eyebrow">${e(DATA.SCENARIOS.find(sc=>sc.id===r.scenario).name)}</p><h3>${r.resolved?'Resolved · Stage '+(r.stage+1):'Advanced to '+e(DATA.SCENARIOS.find(sc=>sc.id===r.scenario).failureLabel).toLowerCase()}</h3><p class="section mono">${r.cost} cost index · ${r.plays} ${r.plays===1?'card':'cards'} played</p></div>`).join('')}</div>`:''}<section class="panel section"><h2>Take it back to the workplace</h2><ol class="muted">${dx?'<li>Which case produced the most disagreement, and why?</li><li>Where do independence and impartiality, or speediness and accountability, differ?</li><li>Which weakness would you investigate first in your national system, and with what evidence?</li>':'<li>Which intervention did you use at the wrong moment?</li><li>What would make another intervention defensible in the same situation?</li><li>Which preventive mechanism would you strengthen in your own workplace?</li>'}</ol><label>One action our team will take<textarea id="takeaway" maxlength="1500" placeholder="The change, who should act, and one first step…">${e(ui.mode==='live'&&ui.live.reflectionDraft!==undefined?ui.live.reflectionDraft:s.reflection)}</textarea></label><div id="takeaway-status" class="takeaway-status">${s.reflection?'Saved with this result.':'Autosaves as you type.'}</div><div class="actions">${button('export-result','Download our result','btn')}${button('print','Print report','btn secondary')}${ui.mode==='practice'?button('new-practice','Start another round','btn secondary'):`${button('standings','Compare teams','btn secondary')}`}</div><p class="small muted section">${ui.mode==='live'?'Your submitted choices and result are saved on the facilitator’s protected board.':'This practice result is saved on this device. You can give the downloaded JSON file to your facilitator for comparison.'}</p></section>${ui.standings?`<section class="panel section"><h2>Team standings</h2>${rankTable(ui.standings.teams,s.game)}</section>`:''}<section class="section"><h2 style="font-size:25px">Every decision, recorded</h2><div class="review-list">${s.log.map(dx?reviewDX:reviewES).join('')||'<p class="muted">No decisions yet.</p>'}</div></section>`;}
function rankTeams(teams,game){return [...teams].sort((a,b)=>game==='diagnostic'?(b.score-a.score)||(b.correct-a.correct):((b.resolved-a.resolved)||(b.progress-a.progress)||(a.cost-b.cost)));}
function rankTable(teams,game){if(!teams.length)return '<div class="empty section">Waiting for teams to join. Share the session code above.</div>';const ranked=rankTeams(teams.map(t=>t.summary?{...t.summary,name:t.name,id:t.id,updatedAt:t.updatedAt}:t),game);return `<div class="table-wrap"><table><thead><tr><th>Place</th><th>Team</th><th>${game==='diagnostic'?'Points':'Resolved'}</th><th>${game==='diagnostic'?'Cases':'Cost index'}</th><th>Status</th></tr></thead><tbody>${ranked.map((t,i)=>`<tr><td class="rank">${i+1}</td><td class="team-name">${e(t.name)}</td><td class="mono">${game==='diagnostic'?t.score+' / '+t.max:t.resolved+' / '+t.total}</td><td class="mono">${game==='diagnostic'?t.progress+' / '+t.total:t.cost+(t.progress<t.total?' · so far':'')}</td><td><span class="badge ${t.done?'good':''}">${t.done?'Finished':'In progress'}</span>${t.updatedAt?`<br><small>Updated ${new Date(t.updatedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small>`:''}</td></tr>`).join('')}</tbody></table></div><p class="small muted section">Compare teams with the same settings. In-progress scores are provisional.${game==='escalation'?' More disputes resolved ranks first; compare cost after teams complete the same disputes.':''} Use the debrief to recognise strong reasoning.</p>`;}
function guide(){return `<section class="guide"><a class="back" href="#hub">← All games</a><p class="eyebrow">For tomorrow’s training</p><h1>Discuss first. Then play.</h1><p class="lead">Use three teams of three, with one phone or laptop per team. A team name is enough. Participants can play independently or join a live facilitator session.</p><div class="grid-two section"><section class="panel"><p class="eyebrow">Session 10 · 09:00–10:30</p><h2>The Diagnostic</h2><p>Diagnose 8, 13 or 18 fictional case files against the ILO’s effectiveness principles. The 13-case mode covers each principle once.</p><ol><li>Read the symptom and discuss the strongest diagnosis.</li><li>Select one principle, optionally record a reason, then lock it in.</li><li>Earn 2 points for a correct answer, or 1 after using a lifeline. Wrong answers earn 0. Two lifelines are available.</li><li>One case accepts either speediness or accountability. The feedback explains both.</li></ol><p class="small">Allow 10–18 minutes including discussion. A short version can replace an existing discussion; it is additional time if simply added to the supplied agenda.</p></section><section class="panel"><p class="eyebrow">Session 11 · 11:00–12:30</p><h2>Stop the Escalation</h2><p>Play one dispute or all three. Starting at a later stage creates a harder rescue challenge.</p><ol><li>Read the current stage and choose one of eleven interventions.</li><li>Discuss the tool and the timing, then play it.</li><li>A holding move keeps the same stage and adds 2 to the cost index. An ineffective move advances the dispute.</li><li>Cards reset for the next dispute. Within a dispute, each card can be used only once.</li></ol><p class="small">Allow 12–20 minutes including the debrief. Cost values are illustrative and do not establish that industrial action or litigation is inappropriate.</p></section></div><section class="panel section"><h2>Run a live team session</h2><ol><li>Open <a href="#facilitator">Facilitator</a> and sign in with your facilitator credentials.</li><li>Create a session for the chosen game, with a duration and settings.</li><li>Share its participant link or eight-character code. Each team joins on one device.</li><li>Use Projector view to show the board. Pause everyone, add 30 seconds or close the session from the facilitator controls.</li><li>Review every team’s choices and reasons separately, then export the session. Restarting a team saves its previous attempt.</li></ol><p class="small">Live sessions need internet access. Moves are saved on the team device before transmission and retried after an interrupted connection. Practice can be played from the downloaded HTML file without internet. Sound is off by default.</p></section><details class="panel section"><summary><strong>The thirteen effectiveness principles</strong></summary><p class="small section">The ILO diagnostic tool uses ten principles for judicial institutions and thirteen for non-judicial institutions. The definitions below are learning paraphrases.</p>${DATA.PRINCIPLES.map(p=>`<p><strong>${p.n}. ${e(p.name)}</strong> — ${e(p.def)}</p>`).join('')}</details><section class="section"><h2 style="font-size:26px">Sources</h2><p class="small section">Case content and interventions adapt the supplied Session 10 and Session 11 materials. ICMS cards reflect the integrated conflict management approach in Session 11; they are not additional ILO instruments.</p><div class="source-list">${DATA.SOURCES.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a>`).join('')}</div></section></section>`;}
function login(){return `<a class="back" href="#hub">← All games</a><section class="panel login-panel"><p class="eyebrow">Protected facilitator access</p><h1>The room, at a glance.</h1><p class="lead" style="font-size:16px">Create sessions, follow teams and review every decision from one board.</p>${errHTML()}<form id="login-form"><label>Username<input id="login-email" name="email" type="email" required autocomplete="username" spellcheck="false"></label><label>Password<input id="login-password" name="password" type="password" required autocomplete="current-password"></label><div class="actions"><button class="btn" ${no(ui.busy)}>${ui.busy?'Signing in…':'Sign in'}</button></div></form><p class="small section">Credentials are verified by the secure results service. Participant games do not require sign-in.</p></section>`;}
function admin(){if(!adminToken)return login();const c=ui.create,b=ui.board,r=b?.room;return `<section class="${ui.projector?'projector':''}"><div class="game-top"><div class="board-intro"><p class="eyebrow">Facilitator board</p><h1>Make the reasoning visible.</h1></div><div class="actions" style="margin:0">${button('projector',ui.projector?'Exit projector view':'Projector view','btn secondary small')}${button('fullscreen','Fullscreen','btn secondary small')}${button('logout','Sign out','btn secondary small')}</div></div>${errHTML()}<details class="panel create-room" ${!ui.rooms.length?'open':''} id="create-panel"><summary><strong>Create a team session</strong></summary><form id="create-form"><div class="fields"><label>Session name<input id="create-name" name="name" maxlength="80" value="${e(c.name)}" required></label><label>Game<select id="create-game" name="game"><option value="diagnostic" ${c.game==='diagnostic'?'selected':''}>The Diagnostic</option><option value="escalation" ${c.game==='escalation'?'selected':''}>Stop the Escalation</option></select></label>${c.game==='diagnostic'?`<label>Case files<select name="count" id="create-count">${[8,13,18].map(n=>`<option value="${n}" ${c.count===n?'selected':''}>${n}${n===13?' · All thirteen principles':''}</option>`).join('')}</select></label>`:`<label>Disputes<select name="scenario" id="create-scenario"><option value="all">All three · Campaign</option>${DATA.SCENARIOS.map(s=>`<option value="${s.id}" ${c.scenario===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label><label>Start at<select name="startStage" id="create-start">${[[0,'Stage 1 · First warning'],[2,'Stage 3 · Formal dispute'],[4,'Stage 5 · Last chance']].map(([n,t])=>`<option value="${n}" ${c.startStage===n?'selected':''}>${t}</option>`).join('')}</select></label>`}<label>Session timer · Minutes<input name="minutes" id="create-minutes" type="number" min="3" max="60" value="${c.minutes}" required></label></div><button class="btn" ${no(ui.busy)}>Create session & get code</button><p class="small section">All teams receive the same cases and settings. A timer reaching zero prompts a debrief; it does not discard answers.</p></form></details>${ui.rooms.length?`<div class="session-list">${ui.rooms.map(room=>button('open-room',`<span class="mono">${e(room.code)} · ${room.teamCount} ${room.teamCount===1?'team':'teams'}</span><b>${e(room.name)}</b><small>${gameName(room.game)} · ${e(room.status)}</small>`,'session-button',`data-code="${e(room.code)}" aria-pressed="${ui.roomCode===room.code}"`)).join('')}</div>`:''}${r?`<section class="board-head"><div><p class="eyebrow">${e(r.name)} · ${gameName(r.game)}</p><div class="room-code">${e(r.code)}</div><small>${r.settings.count&&r.game==='diagnostic'?r.settings.count+' cases':(r.settings.scenario==='all'?'Three disputes':DATA.SCENARIOS.find(s=>s.id===r.settings.scenario)?.name)+' · Start stage '+(r.settings.startStage+1)} · ${e(r.status.toUpperCase())}</small></div><div class="clock-box"><small>ROOM TIMER</small><div class="room-clock" data-admin-clock>${fmt(roomSeconds(r))}</div></div></section><div class="admin-controls"><div class="actions">${button('copy-link','Copy participant link','btn',`data-code="${r.code}"`)}${r.status!=='closed'?button('control',r.status==='paused'?'Resume teams':'Pause teams','btn secondary',`data-control="${r.status==='paused'?'resume':'pause'}" ${no(ui.busy)}`)+button('control','Add 30 seconds','btn secondary',`data-control="extend" ${no(ui.busy)}`)+button('close-room','Close session','btn secondary',no(ui.busy)):''}${button('export-board','Export all responses','btn secondary')}${button('export-csv','Download CSV','btn secondary')}${button('print','Print','btn secondary')}</div><p class="share-link section">Participant link: <a href="${SITE}?room=${r.code}" target="_blank" rel="noopener">${SITE}?room=${r.code}</a></p><p class="small section">The board updates every four seconds. A quiet team remains visible; check their connection if progress stops.</p></div><section class="panel section"><h2>Team standings</h2>${rankTable(b.teams,r.game)}</section><section class="details-area section"><h2 style="font-size:26px">Every team, separately</h2>${b.teams.map(t=>`<details class="panel section" data-detail="${t.id}" ${ui.openDetails.has(t.id)?'open':''}><summary><strong>${e(t.name)}</strong> · ${t.state.log.length} decisions${t.state.phase==='done'?' · Finished':''}</summary><div class="review-list">${t.state.log.map(t.state.game==='diagnostic'?reviewDX:reviewES).join('')||'<p class="muted">No decisions submitted yet.</p>'}</div>${t.state.reflection?`<div class="notice"><strong>Team takeaway</strong><br>${e(t.state.reflection)}</div>`:''}<div class="actions">${button('export-team','Export this team','btn secondary small',`data-id="${t.id}"`)}${button('reset-team','Save attempt & restart','btn secondary small',`data-id="${t.id}" ${no(ui.busy)}`)}</div></details>`).join('')}${b.attempts.length?`<details class="panel section"><summary><strong>${b.attempts.length} saved previous attempts</strong></summary>${b.attempts.map(a=>`<div class="section"><h3 style="font-size:17px">${e(a.state.team)} · ${new Date(a.savedAt).toLocaleString()}</h3><p class="small">${a.state.log.length} decisions saved before restart. Included in the full export.</p></div>`).join('')}</details>`:''}</section>`:`<div class="empty section">${ui.rooms.length?'Select a session to open its board.':'Create your first session, then share its code with the room.'}</div>`}<section class="panel details-area section"><h3>Practice results</h3><p class="small section">If a team played offline, import its downloaded JSON file here. Imported results stay on this facilitator device and are included in a separate export.</p><div class="actions"><label class="btn secondary small" for="import-results">Import team results</label><input id="import-results" type="file" accept="application/json,.json" multiple hidden>${imports.length?button('export-imports','Export imported results','btn secondary small'):''}</div>${imports.length?rankTable(imports.filter(x=>x.game==='diagnostic').map(s=>({name:s.team,...summary(DATA,s)})),'diagnostic')+rankTable(imports.filter(x=>x.game==='escalation').map(s=>({name:s.team,...summary(DATA,s)})),'escalation'):''}</section></section>`;}
function render(){
 const r=route();document.querySelectorAll('nav a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+r?'page':'false'));
 document.title=(r==='facilitator'?'Facilitator':r==='play'||r==='result'?gameName(active()?.game||'diagnostic'):'Labour Dispute Games')+' · ITCILO';
 if(r==='hub')main.innerHTML=hub();else if(r==='diagnostic'||r==='escalation')main.innerHTML=setup(r);else if(r==='guide')main.innerHTML=guide();else if(r==='facilitator')main.innerHTML=admin();else if(r==='play'||r==='result'){const s=active();if(!s){main.innerHTML=hub();return;}main.innerHTML=r==='result'||s.phase==='done'?results(s):s.game==='diagnostic'?diagnostic(s):escalation(s);}else main.innerHTML=hub();
 main.querySelectorAll('[data-detail]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)ui.openDetails.add(d.dataset.detail);else ui.openDetails.delete(d.dataset.detail);}));
 tick();
}
function clearChoice(){ui.selected='';ui.reason='';ui.confidence='sure';ui.standings=null;}
function afterMove(){const s=active();ui.busy=false;ui.error='';persist();if(s?.phase==='done')go('result');else{render();if(s?.phase==='feedback'){$('feedback-title')?.focus();}else window.scrollTo(0,0);}}
async function move(action){
 if(ui.busy)return;
 if(ui.mode==='practice'){
  try{practices[ui.game]=advance(DATA,active(),action);if(action.type!=='hint')clearChoice();else if(active().disabled.includes(ui.selected))ui.selected='';if(['answer','play'].includes(action.type))tone(active().feedback?.right??active().feedback?.kind==='resolve');afterMove();}catch(err){ui.error=err.message;render();}return;
 }
 if(ui.live.pending){ui.error='Retry the saved move before making another choice.';render();return;}
 ui.live.pending={requestId:crypto.randomUUID(),revision:ui.live.team.revision,action};persist();await sendPending();
}
async function sendPending(){if(!ui.live?.pending||ui.busy)return;ui.busy=true;render();try{const r=await api('/team/action',{method:'POST',data:ui.live.pending,token:ui.live.token});const actionType=ui.live.pending.action.type;ui.live.room=r.room;ui.live.team=r.team;delete ui.live.pending;ui.offline=false;if(actionType!=='hint')clearChoice();else if(r.team.state.disabled.includes(ui.selected))ui.selected='';if(['answer','play'].includes(actionType))tone(r.team.state.feedback?.right??r.team.state.feedback?.kind==='resolve');afterMove();}catch(err){if(err.result?.team){ui.live.team=err.result.team;ui.live.room=err.result.room;delete ui.live.pending;clearChoice();ui.error=err.message;}else if(err.status&&err.status!==429){delete ui.live.pending;ui.error=err.message;}else{ui.offline=true;ui.error=err.message;}ui.busy=false;persist();render();}}
async function pullTeam(){if(!ui.live||ui.busy)return;try{const r=await api('/team',{token:ui.live.token});const changed=r.team.revision!==ui.live.team.revision||JSON.stringify(r.room)!==JSON.stringify(ui.live.room)||ui.offline;const reset=r.team.state.startedAt!==ui.live.team.state.startedAt;ui.live.room=r.room;ui.live.team=r.team;ui.offline=false;if(ui.live.pending&&r.team.state.requestIds.includes(ui.live.pending.requestId)){delete ui.live.pending;clearChoice();}if(reset){delete ui.live.pending;clearChoice();toast('The facilitator saved your previous attempt and restarted this team.');}persist();if(changed&&(route()==='play'||route()==='result'))render();}catch{ui.offline=true;}}
async function loadBoard(force=false){if(!adminToken||ui.busy)return;try{const list=await api('/rooms',{token:adminToken});ui.rooms=list.rooms;if(!ui.roomCode||!ui.rooms.some(r=>r.code===ui.roomCode))ui.roomCode=ui.rooms[0]?.code||'';let b=null;if(ui.roomCode)b=await api('/room/'+ui.roomCode,{token:adminToken});const signature=JSON.stringify([list.rooms,b?.room,b?.teams.map(t=>[t.id,t.revision]),b?.attempts.length]);const changed=signature!==ui.boardSignature;ui.boardSignature=signature;ui.board=b;if((force||changed)&&route()==='facilitator')render();}catch(err){if(err.status===401){adminToken='';try{sessionStorage.removeItem('ldg-admin-v2');}catch{}}ui.error=err.message;if(route()==='facilitator')render();}}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
const filename=s=>s.replace(/[^a-z0-9-]/gi,'-').slice(0,60);
function resultPackage(s){return {format:'labour-dispute-games',version:2,exportedAt:new Date().toISOString(),state:s,summary:summary(DATA,s)};}
function csvCell(v){let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function boardCSV(b){const rows=[['session','game','team','attempt','case_or_scenario','stage','choice','outcome','points','cost','reason','confidence','takeaway']];const append=(s,label)=>{for(const l of s.log)rows.push([b.room.code,s.game,s.team,label,l.ref||l.scenario,l.stage===undefined?'':l.stage+1,s.game==='diagnostic'?principle(l.choice)?.name:card(l.card)?.name,s.game==='diagnostic'?(l.right?'correct':'incorrect'):l.kind,l.points??'',l.cost??'',l.reason,l.confidence??'',s.reflection]);if(!s.log.length)rows.push([b.room.code,s.game,s.team,label,'','','','','','','','',s.reflection]);};b.teams.forEach(t=>append(t.state,'current'));b.attempts.forEach((a,i)=>append(a.state,'saved-'+(i+1)));return '\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');}
async function copyLink(code){const link=SITE+'?room='+code;try{await navigator.clipboard.writeText(link);toast('Participant link copied.');}catch{toast('Copy the participant link shown below the controls.');}}
async function handleClick(b){const a=b.dataset.action;if(ui.busy&&!['pause-home','projector','fullscreen'].includes(a))return;
 if(a==='setup-count'){ui.setupCount=Number(b.dataset.count);main.querySelectorAll('[data-action="setup-count"]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));return;}
 if(a==='resume-practice'){ui.mode='practice';ui.game=b.dataset.game;clearChoice();persist();go('play');return;}
 if(a==='resume-live'){ui.mode='live';ui.live=connections.find(c=>c.team.id===b.dataset.id);ui.game=ui.live.team.state.game;clearChoice();persist();go('play');await pullTeam();return;}
 if(a==='pause-home'){persist();go('hub');return;}
 if(a==='select-principle'||a==='select-move'){ui.selected=b.dataset.choice;main.querySelectorAll(a==='select-principle'?'.principle':'.move').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});const commit=main.querySelector('[data-action="'+(a==='select-principle'?'commit-dx':'commit-es')+'"]');if(commit)commit.disabled=false;if($('selection-line'))$('selection-line').textContent='Selected: '+card(ui.selected).name;return;}
 if(a==='commit-dx'){await move({type:'answer',choice:ui.selected,reason:ui.reason,confidence:ui.confidence});return;}
 if(a==='commit-es'){await move({type:'play',choice:ui.selected,reason:ui.reason});return;}
 if(a==='hint'){await move({type:'hint'});return;}
 if(a==='next'){await move({type:'next'});return;}
 if(a==='retry'){await sendPending();return;}
 if(a==='export-result'){download(filename(active().team)+'-'+active().game+'.json',resultPackage(active()));return;}
 if(a==='new-practice'){ui.game=active().game;go(ui.game);return;}
 if(a==='print'){window.print();return;}
 if(a==='standings'){try{ui.standings=await api('/scoreboard/'+ui.live.room.code);render();}catch(err){toast(err.message);}return;}
 if(a==='logout'){try{await api('/logout',{method:'POST',data:{},token:adminToken});}catch{}adminToken='';ui.board=null;ui.rooms=[];try{sessionStorage.removeItem('ldg-admin-v2');}catch{}render();return;}
 if(a==='projector'){ui.projector=!ui.projector;render();return;}
 if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Fullscreen is not available in this browser.');}return;}
 if(a==='open-room'){ui.roomCode=b.dataset.code;ui.board=null;ui.openDetails.clear();try{sessionStorage.setItem('ldg-room-v2',ui.roomCode);}catch{}await loadBoard(true);return;}
 if(a==='copy-link'){await copyLink(b.dataset.code);return;}
 if(a==='control'||a==='close-room'){
  const control=a==='close-room'?'close':b.dataset.control;
  if(control==='close'&&!await confirmAction('Close this session?','Teams will stop making moves. Their responses and results remain saved, and you can export them.'))return;
  ui.busy=true;render();try{await api('/room/'+ui.roomCode+'/control',{method:'POST',data:{action:control},token:adminToken});ui.error='';}catch(err){ui.error=err.message;}ui.busy=false;await loadBoard(true);return;
 }
 if(a==='reset-team'){
  const team=ui.board.teams.find(t=>t.id===b.dataset.id);if(!await confirmAction('Restart '+team.name+'?','The current attempt will be saved in the session history. This team will start the same challenge again. Other teams continue.'))return;
  ui.busy=true;render();try{await api('/room/'+ui.roomCode+'/reset/'+team.id,{method:'POST',data:{},token:adminToken});toast('Previous attempt saved. Team restarted.');}catch(err){ui.error=err.message;}ui.busy=false;await loadBoard(true);return;
 }
 if(a==='export-board'){download('session-'+ui.roomCode+'-all-responses.json',{format:'labour-dispute-games-session',version:2,exportedAt:new Date().toISOString(),...ui.board});return;}
 if(a==='export-csv'){download('session-'+ui.roomCode+'.csv',boardCSV(ui.board),'text/csv;charset=utf-8');return;}
 if(a==='export-team'){const t=ui.board.teams.find(t=>t.id===b.dataset.id);download(filename(t.name)+'-result.json',resultPackage(t.state));return;}
 if(a==='export-imports'){download('imported-practice-results.json',{format:'labour-dispute-games-imports',version:2,states:imports});return;}
}
main.addEventListener('click',evt=>{const b=evt.target.closest('button[data-action]');if(b&&!b.disabled)handleClick(b).catch(err=>{ui.busy=false;ui.error=err.message;render();});});
main.addEventListener('submit',async evt=>{
 evt.preventDefault();const f=evt.target,values=new FormData(f);if(ui.busy)return;
 if(f.id==='practice-form'){
  const game=f.dataset.game,previous=practices[game];if(previous&&previous.phase!=='done'&&previous.log.length&&!await confirmAction('Start a new practice round?','The previous practice round on this device will be replaced. Download its result first if you want to keep it.'))return;
  const settings={count:ui.setupCount,seed:String(values.get('seed')||'workshop-2026'),scenario:values.get('scenario')||'all',startStage:Number(values.get('startStage')||0)};ui.mode='practice';ui.game=game;practices[game]=newGame(DATA,game,settings,String(values.get('team')));clearChoice();persist();go('play');return;
 }
 if(f.id==='join-form'){
  const code=String(values.get('room')||'').trim().toUpperCase(),name=String(values.get('team')||'').trim();if(!/^[A-Z2-9]{8}$/.test(code)){ui.error='Enter the eight-character code shown by your facilitator.';render();return;}
  const old=connections.find(c=>c.room.code===code&&c.team.name.toLowerCase()===name.toLowerCase());if(old){ui.live=old;ui.mode='live';ui.game=old.team.state.game;clearChoice();persist();go('play');await pullTeam();return;}
  ui.busy=true;const submit=f.querySelector('button');submit.disabled=true;submit.textContent='Joining…';try{const r=await api('/join',{method:'POST',data:{code,name}});ui.live={token:r.token,room:r.room,team:r.team};ui.mode='live';ui.game=r.team.state.game;clearChoice();ui.error='';persist();go('play');}catch(err){ui.error=err.message;render();}finally{ui.busy=false;render();}return;
 }
 if(f.id==='login-form'){
  ui.busy=true;f.querySelector('button').textContent='Signing in…';f.querySelector('button').disabled=true;try{const r=await api('/login',{method:'POST',data:{email:values.get('email'),password:values.get('password')}});adminToken=r.token;try{sessionStorage.setItem('ldg-admin-v2',adminToken);}catch{}ui.error='';ui.busy=false;render();await loadBoard(true);}catch(err){ui.error=err.message;ui.busy=false;render();}return;
 }
 if(f.id==='create-form'){
  ui.busy=true;render();try{const settings={count:Number(values.get('count')||13),scenario:String(values.get('scenario')||'all'),startStage:Number(values.get('startStage')||0),minutes:Number(values.get('minutes')||15),seed:crypto.randomUUID()};const r=await api('/rooms',{method:'POST',data:{name:values.get('name'),game:values.get('game'),settings},token:adminToken});ui.roomCode=r.room.code;ui.error='';toast('Session ready. Share the code with your teams.');}catch(err){ui.error=err.message;}ui.busy=false;await loadBoard(true);return;
 }
});
let takeawayTimer;
main.addEventListener('input',evt=>{
 const t=evt.target;if(t.id==='reason')ui.reason=t.value;
 if(t.id==='join-room')t.value=t.value.toUpperCase();
 if(t.id==='takeaway'){
  const value=t.value,s=active();if(ui.mode==='practice'){s.reflection=value;persist();$('takeaway-status').textContent='Saved on this device.';}else{
   $('takeaway-status').textContent='Saving…';clearTimeout(takeawayTimer);takeawayTimer=setTimeout(async()=>{if(ui.busy||ui.live?.pending){$('takeaway-status')&&($('takeaway-status').textContent='Your text is on this device. Reconnect to save it with the session.');ui.live.reflectionDraft=value;persist();return;}ui.live.reflectionDraft=value;persist();await move({type:'reflection',value});if(!ui.live.pending){delete ui.live.reflectionDraft;persist();}},1000);
  }
 }
 if(t.id.startsWith('create-')){const map={'create-name':'name','create-minutes':'minutes'};if(map[t.id])ui.create[map[t.id]]=t.type==='number'?Number(t.value):t.value;}
});
main.addEventListener('change',async evt=>{
 const t=evt.target;if(t.name==='confidence')ui.confidence=t.value;
 if(t.id==='create-game'){ui.create.game=t.value;ui.create.name='22 October · Session '+(t.value==='diagnostic'?'10':'11');render();$('create-panel').open=true;}
 if(t.id==='create-count')ui.create.count=Number(t.value);if(t.id==='create-scenario')ui.create.scenario=t.value;if(t.id==='create-start')ui.create.startStage=Number(t.value);
 if(t.id==='import-results'){
  let count=0;for(const file of t.files){if(file.size>2*1024*1024){toast('Skipped a file larger than 2 MB.');continue;}try{const data=JSON.parse(await file.text()),states=data.state?[data.state]:data.states||[];for(const s of states){if(s.version!==2||!['diagnostic','escalation'].includes(s.game)||!Array.isArray(s.log)||s.log.length>200)continue;const key=s.team+s.startedAt+s.game,index=imports.findIndex(p=>p.team+p.startedAt+p.game===key);if(index>=0)imports[index]=s;else imports.push(s);count++;}}catch{toast('Could not read '+file.name+'. Use a game result JSON file.');}}
  save('ldg-imports-v2',imports);render();toast(count+' practice results imported.');
 }
});
$('sound').addEventListener('click',()=>{ui.sound=!ui.sound;$('sound').textContent=ui.sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(ui.sound));if(ui.sound)tone(true);});
function tick(){const s=active();document.querySelectorAll('[data-elapsed]').forEach(el=>el.textContent=fmt(s?((s.endedAt||Date.now())-s.startedAt)/1000:0));document.querySelectorAll('[data-room-clock]').forEach(el=>el.textContent=fmt(roomSeconds(ui.live.room)));document.querySelectorAll('[data-admin-clock]').forEach(el=>el.textContent=fmt(roomSeconds(ui.board.room)));}
setInterval(tick,1000);
setInterval(async()=>{if(document.hidden||ui.busy)return;if(route()==='facilitator'&&adminToken){await loadBoard();}else if(ui.mode==='live'&&ui.live&&(route()==='play'||route()==='result')){if(ui.live.pending)await sendPending();else if(ui.live.reflectionDraft!==undefined&&ui.live.reflectionDraft!==ui.live.team.state.reflection){const value=ui.live.reflectionDraft;await move({type:'reflection',value});if(!ui.live.pending){delete ui.live.reflectionDraft;persist();}}else await pullTeam();}},4000);
window.addEventListener('hashchange',()=>{ui.error='';render();if(route()==='facilitator'&&adminToken)loadBoard(true);main.focus({preventScroll:true});});
window.addEventListener('online',()=>{if(ui.live?.pending)sendPending();else if(ui.live)pullTeam();});
window.addEventListener('beforeunload',persist);
render();if(route()==='facilitator'&&adminToken)loadBoard(true);if((route()==='play'||route()==='result')&&ui.mode==='live')pullTeam();
})();
